    {tier:"Curator Pass",price:59,priceLabel:"€59",features:["Everything in Night Pass","Hidden collection tour","Reserved artist talk seating"],featured:true},
    {tier:"Patron Pass",price:129,priceLabel:"€129",features:["Everything in Curator Pass","VIP lounge access","Signed event print","Priority entrance"],featured:false}
