  /* =========================================================
     HELPERS
     ========================================================= */

  function $(sel,ctx){return (ctx||document).querySelector(sel);}
  function $$(sel,ctx){return Array.prototype.slice.call((ctx||document).querySelectorAll(sel));}

  function escapeHtml(s){return String(s).replace(/[&<>"']/g,function(c){return{"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c];});}

  function scrollTo(hash){
    var el = $(hash);
    if(el){el.scrollIntoView({behavior:"smooth",block:"start"});}
  }

  /* =========================================================
     RENDER
     ========================================================= */

  function renderTimeline(){
    var container = $("#timeline");
    program.forEach(function(item,index){
      var featured = index===2 || index===3 || index===6;
      var div = document.createElement("div");
      div.className = "timeline-item" + (featured?" featured":"");
      div.innerHTML =
        '<div class="tl-time">'+escapeHtml(item.time)+'</div>'+
        '<div class="tl-title">'+escapeHtml(item.title)+'</div>'+
        '<div class="tl-desc">'+escapeHtml(item.desc)+'</div>'+
        '<span class="tl-loc">'+escapeHtml(item.loc)+'</span>';
      container.appendChild(div);
    });
  }

  function renderArtists(){
    var grid = $("#artistsGrid");
    artists.forEach(function(a,index){
      var card = document.createElement("article");
      card.className = "artist-card";
      card.setAttribute("data-index",index);
      card.setAttribute("tabindex","0");
      card.setAttribute("role","button");
      card.setAttribute("aria-label","View details for "+a.name);
      card.innerHTML =
        '<div class="artist-card-img"><img src="'+escapeHtml(a.img)+'" alt="" loading="lazy"></div>'+
        '<div class="artist-card-body">'+
          '<div class="artist-name">'+escapeHtml(a.name)+'</div>'+
          '<div class="artist-role">'+escapeHtml(a.role)+'</div>'+
          '<p class="artist-teaser">'+escapeHtml(a.teaser)+'</p>'+
          '<span class="artist-link">View details →</span>'+
        '</div>';
      grid.appendChild(card);
    });
  }

  function renderTickets(){
    var grid = $("#ticketsGrid");
    tickets.forEach(function(t){
      var card = document.createElement("div");
      card.className = "ticket-card" + (t.featured?" featured":"");
      var badge = t.featured?'<span class="recommended-badge">Recommended</span>':"";
      var list = t.features.map(function(f){return '<li><svg width="14" height="14" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M5 12l5 5L20 7" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>'+escapeHtml(f)+'</li>';}).join("");
      card.innerHTML =
        badge+
        '<div class="ticket-tier">'+escapeHtml(t.tier)+'</div>'+
        '<div class="ticket-price">'+escapeHtml(t.priceLabel)+'<small>/ person</small></div>'+
        '<ul class="ticket-features">'+list+'</ul>'+
        '<button class="ticket-cta" type="button" data-tier="'+escapeHtml(t.tier)+'">Select '+escapeHtml(t.tier)+'</button>';
      grid.appendChild(card);
    });
  }

  function renderFaq(){
    var list = $("#faqList");
    faqs.forEach(function(f){
      var item = document.createElement("div");
      item.className = "faq-item";
      item.innerHTML =
        '<button class="faq-question" type="button" aria-expanded="false" aria-controls="fa-'+escapeHtml(f.q)+'">'+
          '<span>'+escapeHtml(f.q)+'</span>'+
          '<span class="icon" aria-hidden="true">+</span>'+
        '</button>'+
        '<div class="faq-answer" id="fa-'+escapeHtml(f.q)+'" role="region">'+
          '<div class="faq-answer-inner">'+escapeHtml(f.a)+'</div>'+
        '</div>';
      list.appendChild(item);
    });
  }

  /* =========================================================
     SCROLL REVEAL
     ========================================================= */

  var revealDone = false;
  function runReveal(){
    if(revealDone) return;
    revealDone = true;
    var winH = window.innerHeight;
    $$(".reveal").forEach(function(el){
      var top = el.getBoundingClientRect().top;
      if(top < winH - 80){
        el.classList.add("visible");
      }
    });
  }

  /* =========================================================
     TIMELINE SCROLL REVEAL
     ========================================================= */

  function runTimelineReveal(){
    $$(".timeline-item").forEach(function(el){
      var top = el.getBoundingClientRect().top;
      if(top < window.innerHeight - 60){
        el.classList.add("visible");
      }
    });
  }

  /* =========================================================
     ACTIVE NAV
     ========================================================= */

  var navLinks = $$(".nav-links a");
  var navSections = [
    {id:"concept",label:"concept"},
    {id:"artists",label:"artists"},
    {id:"venue",label:"venue"},
    {id:"tickets",label:"tickets"},
    {id:"faq",label:"faq"}
  ];
  var currentActive = null;

  function updateActiveNav(){
    var scrollY = window.scrollY + 120;
    var active = null;
    for(var i=0;i<navSections.length;i++){
      var sec = navSections[i];
      var el = $( "#"+sec.id );
      if(el){
        var top = el.offsetTop;
        if(scrollY >= top){
          active = sec.label;
        }
      }
    }
    if(!active && window.scrollY < 200){
      active = "concept";
    }
    if(active !== currentActive){
      currentActive = active;
      navLinks.forEach(function(a){
        var match = a.getAttribute("data-nav")===active;
        a.classList.toggle("active",match);
        if(match){a.setAttribute("aria-current","true");}else{a.removeAttribute("aria-current");}
      });
    }
  }

  /* =========================================================
     MOBILE MENU
     ========================================================= */

  var mobileToggle = $("#mobileToggle");
  var navLinksEl = $("#navLinks");

  mobileToggle.addEventListener("click",function(){
    var open = navLinksEl.classList.toggle("open");
    mobileToggle.setAttribute("aria-expanded",open?"true":"false");
  });

  $$(".nav-links a").forEach(function(a){
    a.addEventListener("click",function(){
      navLinksEl.classList.remove("open");
      mobileToggle.setAttribute("aria-expanded","false");
    });
  });

  /* =========================================================
     NAV CLICK → SMOOTH SCROLL
     ========================================================= */

  navLinks.forEach(function(a){
    a.addEventListener("click",function(e){
      var href = a.getAttribute("href");
      if(href && href.charAt(0)==="#"){
        e.preventDefault();
        scrollTo(href);
      }
    });
  });

  $("#navCta").addEventListener("click",function(){
    scrollTo("#tickets");
  });

  /* =========================================================
     ARTIST MODAL
     ========================================================= */

  var artistModal = $("#artistModal");
  var modalClose = $("#modalClose");
  var lastFocused = null;

  function openArtistModal(index){
    var a = artists[index];
    if(!a) return;
    lastFocused = document.activeElement;
    $("#modalImg").src = a.img;
    $("#modalImg").alt = a.name + ", " + a.role;
    $("#modalName").textContent = a.name;
    $("#modalRole").textContent = a.role;
    $("#modalSession").textContent = a.session;
    $("#modalBio").textContent = a.bio;
    $("#modalSessionDetail").textContent = a.session;
    $("#modalRoleDetail").textContent = a.role;
    artistModal.classList.add("open");
    artistModal.setAttribute("aria-hidden","false");
    document.body.style.overflow = "hidden";
    setTimeout(function(){modalClose.focus();},50);
  }

  function closeArtistModal(){
    artistModal.classList.remove("open");
    artistModal.setAttribute("aria-hidden","true");
    document.body.style.overflow = "";
    if(lastFocused && lastFocused.focus){lastFocused.focus();}
  }

  $$(".artist-card").forEach(function(card){
    var handler = function(){
      var idx = parseInt(card.getAttribute("data-index"),10);
      openArtistModal(idx);
    };
    card.addEventListener("click",handler);
    card.addEventListener("keydown",function(e){
      if(e.key==="Enter" || e.key===" "){
        e.preventDefault();
        handler();
      }
    });
  });

  modalClose.addEventListener("click",closeArtistModal);

  artistModal.addEventListener("click",function(e){
    if(e.target === artistModal){
      closeArtistModal();
    }
  });

  document.addEventListener("keydown",function(e){
    if(e.key==="Escape" && artistModal.classList.contains("open")){
      closeArtistModal();
    }
  });

  /* =========================================================
     CHECKOUT MODAL
     ========================================================= */

  var checkoutModal = $("#checkoutModal");
  var checkoutClose = $("#checkoutClose");
  var checkoutForm = $("#checkoutForm");
  var selectedTier = null;
  var lastCheckoutFocus = null;

  function openCheckout(tier){
    var t = null;
    for(var i=0;i<tickets.length;i++){
      if(tickets[i].tier===tier){t=tickets[i];break;}
    }
    if(!t) return;
    selectedTier = t;
    lastCheckoutFocus = document.activeElement;
    $("#checkoutTier").textContent = t.tier;
    $("#checkoutPrice").textContent = t.priceLabel + " / person";
    $("#checkoutTotal").textContent = "€" + (t.price * 1);
    checkoutModal.classList.add("open");
    checkoutModal.setAttribute("aria-hidden","false");
    document.body.style.overflow = "hidden";
    $("#cfName").value = "";
    $("#cfEmail").value = "";
    $("#cfTickets").value = "1";
    $("#cfTerms").checked = false;
    clearFieldError("cfName");
    clearFieldError("cfEmail");
    clearFieldError("cfTickets");
    setTimeout(function(){$("#cfName").focus();},50);
  }

  function closeCheckoutModal(){
    checkoutModal.classList.remove("open");
    checkoutModal.setAttribute("aria-hidden","true");
    document.body.style.overflow = "";
    if(lastCheckoutFocus && lastCheckoutFocus.focus){lastCheckoutFocus.focus();}
  }

  checkoutClose.addEventListener("click",closeCheckoutModal);
  checkoutModal.addEventListener("click",function(e){
    if(e.target === checkoutModal){closeCheckoutModal();}
  });
  document.addEventListener("keydown",function(e){
    if(e.key==="Escape" && checkoutModal.classList.contains("open")){
      closeCheckoutModal();
    }
  });

  $$(".ticket-cta").forEach(function(btn){
    btn.addEventListener("click",function(){
      var tier = btn.getAttribute("data-tier");
      openCheckout(tier);
    });
  });

  /* =========================================================
     CHECKOUT VALIDATION
     ========================================================= */

  function setFieldError(id,show){
    var input = $("#"+id);
    var err = $("#"+id+"Error");
    if(!input || !err) return;
    input.classList.toggle("invalid",show);
    err.classList.toggle("show",show);
  }
  function clearFieldError(id){setFieldError(id,false);}

  function validEmail(v){
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v);
  }

  $("#cfName").addEventListener("input",function(){clearFieldError("cfName");});
  $("#cfEmail").addEventListener("input",function(){clearFieldError("cfEmail");});
  $("#cfTickets").addEventListener("input",function(){clearFieldError("cfTickets");});

  function validateCheckout(){
    var ok = true;
    var name = $("#cfName").value.trim();
    var email = $("#cfEmail").value.trim();
    var ticketsVal = parseInt($("#cfTickets").value,10);
    if(!name){setFieldError("cfName",true);ok=false;}else{clearFieldError("cfName");}
    if(!validEmail(email)){setFieldError("cfEmail",true);ok=false;}else{clearFieldError("cfEmail");}
    if(!ticketsVal || ticketsVal<1 || ticketsVal>8){setFieldError("cfTickets",true);ok=false;}else{clearFieldError("cfTickets");}
    if(!$("#cfTerms").checked){
      toast("Please accept the terms","To continue, accept the reservation terms.");
      ok = false;
    }
    if(!ok){
      var firstInvalid = $("#cfName);
      if(firstInvalid.classList.contains("invalid")) firstInvalid.focus();
      else if($("#cfEmail").classList.contains("invalid")) $("#cfEmail").focus();
      else if($("#cfTickets").classList.contains("invalid")) $("#cfTickets").focus();
    }
    return ok;
  }

  checkoutForm.addEventListener("submit",function(e){
    e.preventDefault();
    if(!validateCheckout()) return;
    var t = selectedTier;
    var count = parseInt($("#cfTickets").value,10);
    var total = t.price * count;
    $("#checkoutTotal").textContent = "€" + total;
    closeCheckoutModal();
    toast(
      "Reservation confirmed",
      t.tier + " — " + count + " ticket" + (count>1?"s":"") + " · €" + total + ". No payment was taken."
    );
  });

  /* =========================================================
     TOAST
     ========================================================= */

  var toastEl = $("#toast");
  var toastTimer = null;

  function toast(title,body){
    $("#toastTitle").textContent = title;
    $("#toastBody").textContent = body;
    toastEl.classList.add("show");
    if(toastTimer) clearTimeout(toastTimer);
    toastTimer = setTimeout(function(){
      toastEl.classList.remove("show");
    },4200);
  }

  /* =========================================================
     NEWSLETTER
     ========================================================= */

  var nlForm = $("#newsletterForm");
  var nlEmail = $("#nlEmail");
  var nlError = $("#nlError");

  nlForm.addEventListener("submit",function(e){
    e.preventDefault();
    var v = nlEmail.value.trim();
    nlError.classList.remove("show");
    nlEmail.classList.remove("invalid");
    if(!v){
      nlError.textContent = "Please enter your email address.";
      nlError.classList.add("show");
      nlEmail.classList.add("invalid");
      nlEmail.focus();
      return;
    }
    if(!validEmail(v)){
      nlError.textContent = "That email doesn't look right. Please check it.";
      nlError.classList.add("show");
      nlEmail.classList.add("invalid");
      nlEmail.focus();
      return;
    }
    nlEmail.value = "";
    nlError.textContent = "";
    toast("You're on the list","We'll send one quiet email before the night.");
  });

  nlEmail.addEventListener("input",function(){
    nlError.classList.remove("show");
    nlEmail.classList.remove("invalid");
  });

  /* =========================================================
     SAVE TO CALENDAR — .ics download
     ========================================================= */

  function downloadIcs(){
    var title = "ARTIFACT: Museum Night";
    var location = "The Old Gallery, Warsaw";
    var desc = "A cinematic after-hours museum event with exhibitions, performances, talks, and guided tours.";
    var start = "20261018T190000";
    var end = "20261019T020000";
    var now = new Date().toISOString().replace(/[-:]/g,"").split(".")[0] + "Z";

    var lines = [
      "BEGIN:VCALENDAR",
      "VERSION:2.0",
      "PRODID:-//ARTIFACT//Museum Night//EN",
      "CALSCALE:GREGORIAN",
      "METHOD:PUBLISH",
      "BEGIN:VEVENT",
      "DTSTAMP:"+now,
      "DTSTART:"+start,
      "DTEND:"+end,
      "SUMMARY:"+escapeCsv(title),
      "LOCATION:"+escapeCsv(location),
      "DESCRIPTION:"+escapeCsv(desc),
      "END:VEVENT",
      "END:VCALENDAR"
    ];
    var body = lines.join("\r\n");
    var blob = new Blob([body],{type:"text/calendar;charset=utf-8"});
    var url = URL.createObjectURL(blob);
    var a = document.createElement("a");
    a.href = url;
    a.download = "artifact-museum-night.ics";
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(function(){URL.revokeObjectURL(url);},1000);
    toast("Calendar saved","artifact-museum-night.ics downloaded.");
  }

  function escapeCsv(s){
    s = String(s);
    if(s.indexOf(",")>-1 || s.indexOf(";")>-1 || s.indexOf("\n")>-1 || s.indexOf('"')>-1){
      s = s.replace(/"/g,'""');
      return '"'+s+'"';
    }
    return s;
  }

  $("#heroCalendarBtn").addEventListener("click",downloadIcs);

  /* =========================================================
     INIT
     ========================================================= */

  renderTimeline();
  renderArtists();
  renderTickets();
  renderFaq();

  window.addEventListener("load",function(){
    runReveal();
    runTimelineReveal();
  });

  var scrollTimer = null;
  window.addEventListener("scroll",function(){
    if(scrollTimer) cancelAnimationFrame(scrollTimer);
    scrollTimer = requestAnimationFrame(function(){
      updateActiveNav();
      runTimelineReveal();
    });
  },{passive:true});

  window.addEventListener("resize",function(){
    runReveal();
    runTimelineReveal();
  });

  runReveal();
  runTimelineReveal();
  updateActiveNav();

})();
</script>
</body>
